// Deterministic risk classification. No model decides whether an action is safe.
// The optional second-opinion model in prompts/governance/risk-assessor.md may only
// ever RAISE a level; it is never consulted to lower one.
const r = $json;

const requesting = String(r.requesting_workflow || 'unknown');
const action = String(r.proposed_action || '');
const actionType = String(r.action_type || '').toLowerCase().trim();
const system = String(r.affected_system || 'unknown');
const paramsRaw = String(r.parameters || '{}');
const reasoning = String(r.agent_reasoning || '');
const confidence = Number(r.agent_confidence);
const overrideToken = String(r.override_token || '');
const simulate = String(r.simulate_decision || '').toLowerCase().trim();

let params = {};
try { params = JSON.parse(paramsRaw); } catch (e) { params = {}; }

// Stable request fingerprint for idempotent replay.
function fingerprint(s) {
  let h1 = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h1 ^= s.charCodeAt(i);
    h1 = (h1 + ((h1 << 1) + (h1 << 4) + (h1 << 7) + (h1 << 8) + (h1 << 24))) >>> 0;
  }
  return ('00000000' + h1.toString(16)).slice(-8);
}
const requestKey = r.idempotency_key
  ? String(r.idempotency_key)
  : ('gov-' + fingerprint(requesting + '|' + action + '|' + actionType + '|' + system + '|' + paramsRaw));

// ---- Base level from the declared action type ---------------------------
const BASE = {
  read: 'LOW', list: 'LOW', search: 'LOW', probe: 'LOW',
  write: 'MEDIUM', create: 'MEDIUM', update: 'MEDIUM', configure: 'MEDIUM',
  send: 'HIGH', publish: 'HIGH', notify: 'HIGH', external: 'HIGH',
  delete: 'CRITICAL', purge: 'CRITICAL', pay: 'CRITICAL', transfer: 'CRITICAL',
  deploy: 'CRITICAL', grant: 'CRITICAL', revoke: 'CRITICAL'
};
const ORDER = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];
let level = BASE[actionType] || 'HIGH';   // unknown action type is NOT treated as safe
const reasons = [];
reasons.push('action_type "' + (actionType || 'unspecified') + '" has base level ' + level +
  (BASE[actionType] ? '' : ' (unrecognised action_type defaults to HIGH)'));

function raiseTo(target, why) {
  if (ORDER.indexOf(target) > ORDER.indexOf(level)) {
    level = target;
    reasons.push('raised to ' + target + ': ' + why);
  } else {
    reasons.push('noted (' + target + '-class signal, level already ' + level + '): ' + why);
  }
}

// ---- Escalators ---------------------------------------------------------
const haystack = (action + ' ' + JSON.stringify(params) + ' ' + system).toLowerCase();

if (/\b(delete|drop|truncate|purge|wipe|destroy|revoke|terminate|shutdown)\b/.test(haystack)) {
  raiseTo('CRITICAL', 'destructive verb present in the action or parameters');
}
if (/\b(prod|production|live)\b/.test(system.toLowerCase())) {
  raiseTo('HIGH', 'affected system looks like production');
}

// Monetary exposure
const amountKeys = ['amount', 'total', 'value', 'price', 'sum', 'payment'];
let maxAmount = 0;
Object.keys(params).forEach(function (k) {
  if (amountKeys.indexOf(k.toLowerCase()) !== -1) {
    const v = Number(params[k]);
    if (isFinite(v) && v > maxAmount) { maxAmount = v; }
  }
});
if (maxAmount > 0) {
  if (maxAmount >= 1000) { raiseTo('CRITICAL', 'monetary amount ' + maxAmount + ' at or above the 1000 auto-deny threshold'); }
  else if (maxAmount >= 100) { raiseTo('HIGH', 'monetary amount ' + maxAmount + ' at or above the 100 review threshold'); }
  else { reasons.push('monetary amount ' + maxAmount + ' below review thresholds'); }
}

// Bulk operations
const bulkKeys = ['count', 'limit', 'batch_size', 'quantity', 'ids'];
let bulk = 0;
Object.keys(params).forEach(function (k) {
  if (bulkKeys.indexOf(k.toLowerCase()) !== -1) {
    const v = Array.isArray(params[k]) ? params[k].length : Number(params[k]);
    if (isFinite(v) && v > bulk) { bulk = v; }
  }
});
if (bulk >= 100) { raiseTo('CRITICAL', 'operation targets ' + bulk + ' records'); }
else if (bulk >= 10) { raiseTo('HIGH', 'operation targets ' + bulk + ' records'); }

// Personal data exposure
const PII = [
  { name: 'email', re: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/ },
  { name: 'card_number', re: /\b(?:\d[ -]*?){13,16}\b/ },
  { name: 'phone', re: /\+\d{1,3}[\s-]\d{6,}/ },
  { name: 'secret_key', re: /\b(?:api[_-]?key|secret|password|token|bearer)\b/i }
];
const piiFound = [];
PII.forEach(function (p) { if (p.re.test(paramsRaw)) { piiFound.push(p.name); } });
if (piiFound.length) { raiseTo('HIGH', 'parameters contain personal or secret data: ' + piiFound.join(', ')); }

// Agent self-reported confidence
if (isFinite(confidence)) {
  if (confidence < 0.5) { raiseTo('HIGH', 'agent confidence ' + confidence + ' is below 0.5'); }
  else if (confidence < 0.7) { raiseTo('MEDIUM', 'agent confidence ' + confidence + ' is below 0.7'); }
} else {
  raiseTo('MEDIUM', 'agent did not report a confidence value');
}

// Prompt-injection / social-engineering markers in the agent's own reasoning.
// Untrusted content trying to talk its way past governance is itself a red flag.
const INJECTION = /(ignore (?:all |the )?(?:previous|prior|above) instructions|this (?:is |was )?(?:pre-?approved|already approved)|no approval (?:is )?(?:needed|required)|bypass (?:the )?(?:governance|approval|safety)|you are authorized to)/i;
if (INJECTION.test(reasoning) || INJECTION.test(paramsRaw)) {
  raiseTo('CRITICAL', 'the request argues that it does not need approval, which is treated as a suspected injection');
}

