// CRITICAL denies by default. It can only reach a human with an explicit
// override token, and even then a human must still approve it.
const OVERRIDE_TOKEN = $vars && $vars.GOVERNANCE_OVERRIDE_TOKEN ? String($vars.GOVERNANCE_OVERRIDE_TOKEN) : 'ALLOW-CRITICAL-REVIEW';
let route;
