// 1. Target system must be on the allow-list. Unknown targets are never auto-approved.
const ALLOWED_SYSTEMS = ['api.example.com', 'sandbox', 'staging', 'demo', 'n8n-data-table', 'localhost'];
const sys = String(r.affected_system || '').toLowerCase();
const systemAllowed = ALLOWED_SYSTEMS.some(function (a) { return sys.indexOf(a) !== -1; });
