let reason;
if (errored) {
  decision = 'rejected';
  reason = 'Approval channel failed, so the request was denied by the fail-closed rule: ' + String(res.error).slice(0, 300);
} else if (approved) {
  decision = 'approved';
  reason = 'Human approver accepted the request in Telegram.';
} else {
  decision = 'rejected';
  reason = 'Human approver rejected the request, or the approval window expired without a response.';
}

return {
  json: Object.assign({}, req, {
    decision: decision,
