else { route = (overrideToken && overrideToken === OVERRIDE_TOKEN) ? 'human' : 'deny'; }

const nowMs = Date.now();
const EXPIRY_MINUTES = 60;

return {
  json: {
    request_key: requestKey,
    requesting_workflow: requesting,
    proposed_action: action,
    action_type: actionType,
    affected_system: system,
    parameters: paramsRaw,
    parameters_parsed: params,
    agent_reasoning: reasoning,
    agent_confidence: isFinite(confidence) ? confidence : null,
    simulate_decision: simulate,
    risk_level: level,
    risk_reasons: reasons,
    signals: { max_amount: maxAmount, bulk_count: bulk, pii_found: piiFound },
    route: route,
    deny_reason: route === 'deny'
      ? 'CRITICAL operations are denied by default. Supply a valid override_token to route this to a human reviewer instead.'
      : null,
    requested_at: new Date(nowMs).toISOString(),
    expires_at: new Date(nowMs + EXPIRY_MINUTES * 60000).toISOString(),
    expiry_minutes: EXPIRY_MINUTES,
    started_at_ms: nowMs
  }
};

// MEDIUM risk gets extra DETERMINISTIC validation rather than a human.
// If every check passes the operation proceeds; any failure escalates to a human.
const r = $json;
const p = r.parameters_parsed || {};
const checks = [];

function check(name, passed, detail) { checks.push({ name: name, passed: passed, detail: detail }); }

// 1. Target system must be on the allow-list. Unknown targets are never auto-approved.
const ALLOWED_SYSTEMS = ['api.example.com', 'sandbox', 'staging', 'demo', 'n8n-data-table', 'localhost'];
const sys = String(r.affected_system || '').toLowerCase();
const systemAllowed = ALLOWED_SYSTEMS.some(function (a) { return sys.indexOf(a) !== -1; });
check('target_system_allowlisted', systemAllowed,
  systemAllowed ? sys + ' is on the allow-list' : sys + ' is not on the MEDIUM auto-approve allow-list');

// 2. Parameter payload must be small. A huge payload is a sign of an unintended bulk operation.
const size = String(r.parameters || '').length;
check('payload_size_within_limit', size <= 8192, 'payload is ' + size + ' bytes, limit 8192');

// 3. No parameter key may look like a credential.
const badKeys = Object.keys(p).filter(function (k) { return /(password|secret|token|api[_-]?key|private[_-]?key)/i.test(k); });
check('no_credential_parameters', badKeys.length === 0,
  badKeys.length ? 'credential-like keys present: ' + badKeys.join(', ') : 'no credential-like parameter keys');

// 4. No wildcard or unbounded selector.
const paramStr = JSON.stringify(p);
const wildcard = /"\*"|\ball\b|\bwhere\s+1\s*=\s*1\b/i.test(paramStr);
check('no_unbounded_selector', !wildcard, wildcard ? 'parameters contain a wildcard or unbounded selector' : 'selectors are bounded');

// 5. The agent must have given a non-trivial reason.
const reasonOk = String(r.agent_reasoning || '').trim().length >= 20;
check('reasoning_present', reasonOk, reasonOk ? 'agent supplied reasoning' : 'agent reasoning is missing or too short to review');

const failed = checks.filter(function (c) { return !c.passed; });
const passed = failed.length === 0;

return {
  json: Object.assign({}, r, {
    validation_checks: checks,
    validation_passed: passed,
    validation_failures: failed.map(function (c) { return c.name + ': ' + c.detail; })
  })
};

