// Fail closed. Anything that is not an explicit approval is a rejection:
// a timeout, a delivery failure, an unreachable approver, a malformed payload.
const req = $('Escalate to Human').first().json;
const res = $json || {};
const approved = res.data && res.data.approved === true;
const errored = !!res.error;

let decision;
let reason;
if (errored) {
  decision = 'rejected';
  reason = 'Approval channel failed, so the request was denied by the fail-closed rule: ' + String(res.error).slice(0, 300);
} else if (approved) {
  decision = 'approved';
  reason = 'Human approver accepted the request in Telegram.';
} else {
  decision = 'rejected';
  reason = 'Human approver rejected the request, or the approval window expired without a response.';
}

return {
  json: Object.assign({}, req, {
    decision: decision,
    decided_by: errored ? 'policy:fail_closed_channel_error' : 'human:telegram',
    decision_reason: reason
  })
};

